<?php require 'includes/config.php';$pageTitle='Shop';$cat=$_GET['category']??'';$sql="SELECT * FROM products WHERE status='active'";$params=[];if($cat){$sql.=" AND category=?";$params[]=$cat;}$sql.=" ORDER BY id DESC";$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();include 'includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">Complete catalogue</span><h1>Shop NovaCart</h1><p>Search, filter and discover products across our premium catalogue.</p><div class="search-strip"><input id="shop-search" placeholder="Search products by name..."><select onchange="location='shop.php?category='+encodeURIComponent(this.value)"><option value="">All categories</option><?php foreach(['Fashion','Technology','Home','Beauty'] as $c):?><option <?=($cat==$c?'selected':'')?> value="<?=$c?>"><?=$c?></option><?php endforeach;?></select></div></div></section>
<section class="section"><div class="container"><div class="product-grid"><?php foreach($products as $p):?><article class="product-card" data-name="<?=e(strtolower($p['name']))?>"><a class="product-media" href="product.php?id=<?=$p['id']?>"><button type="button" class="wishlist-btn" data-wish='<?=e(json_encode(['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'image'=>$p['image']]))?>'>♡</button><img src="<?=e($p['image'])?>"></a><div class="product-body"><span class="cat"><?=e($p['category'])?></span><h3><?=e($p['name'])?></h3><div class="product-meta"><span class="price">LKR <?=number_format($p['price'],2)?></span><span class="rating">★★★★★</span></div><button class="add-btn" data-add='<?=e(json_encode(['id'=>$p['id'],'name'=>$p['name'],'price'=>$p['price'],'image'=>$p['image']]))?>'>Add to cart</button></div></article><?php endforeach;?></div></div></section><?php include 'includes/footer.php';?>
